<?php require_once __DIR__.'/../includes/bootstrap.php'; require_login(); if(!hash_equals($_SESSION['csrf']??'',$_GET['csrf']??'')){http_response_code(419);exit;} $id=(int)$_GET['id'];$albumId=(int)$_GET['album_id'];$s=$pdo->prepare('SELECT audio_file FROM tracks WHERE id=? AND album_id=?');$s->execute([$id,$albumId]);$t=$s->fetch();if($t){@unlink(dirname(__DIR__).'/uploads/audio/'.$t['audio_file']);$pdo->prepare('DELETE FROM tracks WHERE id=?')->execute([$id]);}flash('success','Titel gelöscht.');redirect('admin/album_edit.php?id='.$albumId);
